int is_prime(int m)
{
		int	fc=0,i;
	for(i=1;i<=m;i++)
	{

		if(m%i==0)
		{
			fc=fc+1;			
		}
	}
	return fc==2;
}


int pre_prime(int n)
{
	while (is_prime(n) == 0)
	{
		n--;
	}
	return n;
}
int nex_prime(int n)
{
	while(is_prime(n)==0)
	{
		n++;
	}
	return n;
}

